\label{thickAlt}
    Property (GP3) is equivalent to the following, see for instance \cite{Hendrik}:
    \textit{
    \begin{enumerate}[(GP3')]
		\item Every point is incident with at least three lines and every line is incident with at least three points. 
	\end{enumerate}}

(See e.g. \cite[Theorem 1.5.10]{Hendrik})\label{incidenceGraph}
	Let \(\Gamma\) be a point-line geometry with at least two points and the properties that:
	\begin{itemize}
		\item every point is incident with at least two lines;
		\item every line is incident with at least two points.
	\end{itemize}
	Then, \(\Gamma\) is a weak generalised \(n\)-gon if and only if its incidence graph has diameter \(n\) and girth \(2n\).

(See e.g. \cite[Theorem 1.3.5]{Hendrik})
\label{uniqueClosest}
	Let \(p\) be a point and \(L\) be a line of a weak generalised \(2m\)-gon \(\Gamma\), $m\geq 2$. Then there is a unique point on \(L\) closest (that is, at smallest distance) to \(p\).

(Feit \& Higman \cite{FEITHIGMAN})
	Let \(\Gamma\) be a finite weak generalised \(n\)-gon of order \((s,t)\) with \(n\ge 3\). Then one of the following holds:
	\begin{enumerate}[(i)]
		\item \(s=t=1\), and \(\Gamma\) is an ordinary \(n\)-gon;
		\item \(n=3,s=t>1\), and \(\Gamma\) is a projective plane;
		\item \(n = 4\) and \(\frac{st(1+st)}{s+t}\) is an integer;
		\item \(n=6\) and if \(s,t>1\), then \(st\) is a perfect square;
		\item \(n=8\) and if \(s,t>1\) then \(2st\) is a perfect square;
		\item \(n=12\) and \(s=1\) or \(t=1\). 
	\end{enumerate}

Let \(\Gamma\) be a finite thick generalised \(n\)-gon of order \((s,t)\) with \(n\ge 4\). Then one of the following holds:
	\begin{enumerate}[(i)]
		\item (Higman \cite{Higman}) \(n = 4 \) and \(s\le t^2\), dually \(t\le s^2\);
		\item (Haemers \& Roos \cite{HaemersAndRoos}) \(n = 6\) and \(s\le t^3\), dually \(t\le s^3\);
		\item (Higman \cite{Higman}) \(n = 8\) and \(s\le t^2\), dually \(t\le s^2\).

	\end{enumerate}

\label{def}
	Let \(\mathbb{F}\) be a field and let $\mathcal{P}$ be a set. 
    \begin{itemize}
    \item \(\mathbb{F}\mathcal{P}\) is the vector space of \(\mathbb{F}\)-valued functions on the set \(\mathcal{P}\); 
    \item For a subspace 
	 \(\mathfrak{M}\) of \(\mathbb{F}\mathcal{P}\), its {\em dual}, \(\mathfrak{M}^D\), is the subspace of all \(\mathfrak{f}\in \mathbb{F}\mathcal{P}:\) 
	\[\forall \mathfrak{g}\in\mathfrak{M}: \sum_{x\in\mathcal{P}}\mathfrak{f}(x)\cdot\mathfrak{g}(x) = 0;\]
    \item	For a subset \(S\) of \(\mathcal{P}\),  its {\em indicator function} \(\mathfrak{i}_{S} \in \mathbb{F}\mathcal{P}\) is given by  \[\mathfrak{i}_{S}:\mathcal{P}\to \mathbb{F}:p\mapsto \mathfrak{i}_{S}(p) = \begin{cases}
		1 &\text{ if } p\in S \\
		0 &\text{ if } p\not\in S
	\end{cases};\]
    \item For \(\mathfrak{f}\in\mathbb{F}\mathcal{P}\),  the {\em support} of \(\mathfrak{f}\), denoted as \(\text{supp}(\mathfrak{f})\), is the set \(\{x\in\mathcal{P}\mid \mathfrak{f}(x)\neq 0\}\); 
    \item The weight of a vector $\mathfrak{f}\in \mathbb{F}\mathcal{P}$ is the size of $\text{supp}(\mathfrak{f})$.
    \end{itemize}

\label{possibleZero}
	Let \(\mathbb{F}\) be a field and let \(k\) be a natural number. We see that
	\(k\cdot 1_\mathbb{F} := 1_\mathbb{F}+1_\mathbb{F}+\dots+1_\mathbb{F} \text{ (\(k\) times)}\) and \( -k\cdot 1_\mathbb{F} := -(k\cdot 1_\mathbb{F}) \) are elements of \(\mathbb{F}\). This allows us to evaluate any integer in \(\mathbb{F}\) and, with some abuse of notation, use integers as parameters in \(\mathbb{F}\). Note however, that it is possible for this parameter to evaluate to \(0\) in \(\mathbb{F}\).

\label{gammaProperties}

	\begin{enumerate}[(i)]
		\item For a point \(x\in\mathcal{P}\), \(\mathcal{P}_i(x) = \emptyset\) if $i$ is odd, and   \(\mathcal{P}_i(x) = \Gamma_i(x)\) if $i$ is even.
		\item For a line \(L\in\mathcal{L}\), \(\mathcal{P}_i(L) = \Gamma_i(L)\) if $i$ is odd and \(\mathcal{P}_i(L) = \emptyset\) if $i$ is even. 




	\end{enumerate}

\label{starLemma}
	Let \(C\) be a set of points of $\Gamma$ with \(|C|<s+1\). Let \(d\in \{1,2,\dots,m-1\}\).
	\begin{enumerate}[(i)]
		\item \(\forall L \in \mathcal{L}: \exists M \in \mathcal{L}_{\le 2d-2}(L): C\cap \mathcal{P}_{\le2d-1}(M) = C\cap \mathcal{P}_{1}(L)\).
		\item \(\forall L \in \mathcal{L}: \exists v \in \mathcal{P}_{\le 2d-1}(L): C\cap \mathcal{P}_{\le2d}(v) = C\cap \mathcal{P}_{1}(L)\).
	\end{enumerate}

\label{smallC}
	Let \(C\) be an $\mathcal{X}-$blocking set,
	then \(|C|\ge s+1\).

\label{traceLines}

	Assume that \(s\le t\). Let $C$ be an $\mathcal{X}-$blocking set.
	Let \(x\) be an element of \(\Gamma\) such that for some \(d\in\{1,\dots,2m-2\}\):
	\begin{itemize}
		\item \(\mathcal{P}_d(x)\) contains at least two points of \(C\).
		\item \(\mathcal{P}_{\le d-1}(x)\) contains no points of \(C\).
	\end{itemize}
Then, $C$ is a $\mathcal{Y}-$blocking set where $\mathcal{Y}=\{\mathcal{P}_{d-1}(y)\mid y\in \Gamma_1(x)\}.$

Let \(x\) be a point of \(\Gamma\). The {\em perp-geometry} of a point \(x\) in \(\Gamma\) is the point-line geometry \((\mathcal{P}',\mathcal{L}',\mathtt{I}')\) with
	\begin{itemize}
		\item \(\mathcal{P}' = \mathcal{P}_{ 2}(x)\),
		\item \(\mathcal{L}' = \mathcal{L}_{ 1}(x) \cup \{T_{2,x,y}\mid y\in\mathcal{P}, y\text{ is opposite } x\}\),
		\item \(\mathtt{I}'\) defined naturally from \(\mathtt{I}\) and \(\in\).
	\end{itemize}

\label{cxcy}
	Let \(v\) and \(w\) be two points of \(\Gamma\). 
	Then, \(\mathfrak{c}_{v}-\mathfrak{c}_w \in \mathfrak{C}_{\mathbb{F}}^D\).

Let $L$ be a line.	Using Lemma \ref{cx1} we see that
	\begin{align*}
		\langle\mathfrak{c}_{v}-\mathfrak{c}_w, \mathfrak{i}_L\rangle  =  \langle\mathfrak{c}_{v}, \mathfrak{i}_L\rangle - \langle\mathfrak{c}_w, \mathfrak{i}_L\rangle = 1 - 1 = 0.     
	\end{align*}
    Since $\mathfrak{C}_\mathbb{F}$ is generated by the vectors $\mathfrak{i}_L$, where $L\in \mathcal{L}$, the statement follows.

\label{smallcx}  

	Let \(\mathfrak{c}\in \mathbb{F}\mathcal{P}\) and let \(C\) be the support of \(\mathfrak{c}\). If
	\[\forall L \in \mathcal{L}: \exists v \in \mathcal{P}: L \text{ is covered by } \mathfrak{c}_{v} \text{ and } \langle \mathfrak{c}, \mathfrak{c}_{v} \cdot \mathfrak{i}_L \rangle = 0\] then \(|C|> t + 1\).

\label{alsoLines}
	Let \(\mathfrak{c}\in \mathbb{F}\mathcal{P}\) and let \(C\) be the support of \(\mathfrak{c}\). Assume that \(|C|=s+1\) and
	let \(L\) be a line containing a point \(v\) of \(C\). Then,  
	\[\exists w \in \mathcal{P}_{\le 2m-3}(L): \langle \mathfrak{c}_w\cdot \mathfrak{i}_L ,\mathfrak{c}\rangle = \langle \mathfrak{c}_w,\mathfrak{c}\rangle.\]
